pub(crate) struct RuntimeAdmission {
    app: AppState,
    node: NodeState,
    lease: SessionLease,
    sensitive: Option<crate::app_lock::SensitiveAction>,
}

impl RuntimeAdmission {
    pub(crate) fn capture(
        app: &AppState,
        node: &NodeState,
        owner: &str,
    ) -> Result<Self, CommandError> {
