                    app: app.clone(),
                    node: node.clone(),
                    lease: lease.clone(),
                    sensitive: None,
                })
            })
            .map_err(CommandError::Authorization)?
    }

    fn capture_for(
        app: &AppState,
        node: &NodeState,
        owner: Option<&str>,
    ) -> Result<Self, CommandError> {
        let lease = app
            .session()
            .capture()
            .map_err(CommandError::Authorization)?;
